// Groq-hosted models do not reliably support native (OpenAI-style) tool
// calling — they often emit tool syntax as plain text with finish_reason
// "stop", which used to end the run with no actions and no disposition.
// So we never send the `tools` param; ALL models use the fenced-JSON
// action protocol parsed from text. Compound systems additionally need
// the latest model version header.
const isCompound = /^groq\/compound/.test(model);
const extraHeaders = isCompound ? { "Groq-Model-Version": "latest" } : undefined;
const toolsEnabled = false;
const textActionsEnabled = openaiTools.length > 0 && toolInvoke !== null;
if (textActionsEnabled) {
    const toolDoc = openaiTools
        .map((t) => `- ${t.function.name}: ${t.function.description ?? ""}\n  parameters: ${JSON.stringify(t.function.parameters)}`)
        .join("\n");
    const protocolInsertAt = messages.findIndex((m) => m.role !== "system");
    messages.splice(protocolInsertAt === -1 ? messages.length : protocolInsertAt, 0, {
        role: "system",
        content: [
            "You act on the Paperclip control plane by emitting action blocks. These Paperclip tools are the ONLY way to perform real actions — narrating an action without emitting its block does nothing.",
            "To call a tool, output an XML block with tag `tool` containing a single JSON object:",
            '<tool>\n{"tool": "<tool name>", "args": { ... }}\n</tool>',
            "Emit exactly ONE tool block per reply, then stop. The block is executed and its result is sent back to you; then you continue or finish. Never emit the same tool call twice unless the first attempt returned an error.",
            "Only claim an action happened if you emitted its block and saw an ok result for it.",
            "Before you finish, you MUST record a final disposition on the issue you are working on via paperclip_update_issue_status (done when complete, in_review when awaiting review, blocked when stuck). A run that ends without a disposition is treated as failed.",
            "Available tools:",
            toolDoc,
        ].join("\n\n"),
    });
}
